-- Q-GANG historical membership bridge + birthday notices
create table if not exists public.legacy_members (id bigint generated by default as identity primary key,legacy_nickname text not null unique,joined_at date not null,birth_date date,legacy_rank text,legacy_status text not null default 'active',claimed_by uuid unique references public.profiles(id) on delete set null,claimed_at timestamptz,verified_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),constraint legacy_nickname_nonempty check(char_length(trim(legacy_nickname)) between 2 and 40));
alter table public.legacy_members enable row level security;revoke all on table public.legacy_members from anon,authenticated;
insert into public.legacy_members(legacy_nickname,joined_at,birth_date,legacy_rank,legacy_status) values
('Quadismic','2008-01-01','1996-03-27','Lider','active'),('Shrapnellx','2008-01-01','1996-03-23','Gözlemci','inactive'),('Forsaken','2016-01-01','2005-06-18','Üye','active'),('HanlyX','2017-03-13','2000-03-13','Üye','active'),('BonusKafa','2018-08-17','2002-08-13','Üye','active'),('Renovich','2018-08-23','2002-06-02','Vekilharç','active'),('SaintDark','2018-11-09','2006-11-27','Üye','active'),('Pancroft','2019-04-12','2005-07-27','Üye','active'),('bekir','2019-06-12','2005-10-18','Üye','active'),('Casanovian','2020-04-17','2006-12-19','Üye','active'),('TrAzIS','2020-04-17','2005-01-28','Gözlemci','inactive'),('Lincoln','2020-07-27','2007-04-02','Üye','active'),('Muhtar','2020-11-26','2006-10-16','Üye','active'),('Schizo','2020-12-19','2005-05-29','Teğmen','active'),('JUSTilknur','2021-08-09','2004-04-26','Üye','active'),('CoocooliKoo','2022-02-14','2006-07-20','Üye','active'),('Ranmaru','2022-04-20','2004-12-15','Üye','active'),('Kyklos','2023-11-20','2005-04-21','Üye','active'),('Yalvach','2024-03-02','2005-12-28','Üye','active'),('Gaspare','2025-07-29','2005-03-16','Üye','active'),('Yarenna','2025-07-29','2001-03-03','Gözlemci','inactive'),('Lillycha','2025-11-12','2001-05-09','Üye','active'),('Sheila','2025-11-12','2007-08-07','Üye','active'),('TheFallingPlane','2025-11-25','1995-07-01','Gözlemci','inactive'),('Molly','2025-11-25','2007-06-04','Gözlemci','inactive'),('Hamzah','2026-03-18','2003-05-23','Gözlemci','inactive'),('p3naMi','2026-05-21','2005-06-24','Gözlemci','inactive'),('lazziyo','2026-05-22','2008-05-09','Gözlemci','inactive') on conflict(legacy_nickname) do update set joined_at=excluded.joined_at,birth_date=excluded.birth_date,legacy_rank=excluded.legacy_rank,legacy_status=excluded.legacy_status;
create or replace function public.list_legacy_member_matches() returns table(legacy_id bigint,legacy_nickname text,joined_at date,birth_date date,legacy_rank text,legacy_status text,target_user_id uuid,target_display_name text,target_handle text) language plpgsql stable security definer set search_path='public','private','pg_temp' as $$ begin if auth.uid() is null or not private.has_permission('members.manage') then raise exception 'not authorized';end if;return query select l.id,l.legacy_nickname,l.joined_at,l.birth_date,l.legacy_rank,l.legacy_status,p.id,p.display_name,p.handle from public.legacy_members l join public.profiles p on l.claimed_by is null and(lower(p.handle)=lower(l.legacy_nickname) or lower(p.display_name)=lower(l.legacy_nickname)) order by l.joined_at,l.legacy_nickname;end$$;revoke all on function public.list_legacy_member_matches() from public;grant execute on function public.list_legacy_member_matches() to authenticated;
create or replace function public.link_legacy_member(p_legacy_id bigint,p_target_user uuid) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare l public.legacy_members%rowtype;era_no integer;next_no bigint;begin if auth.uid() is null or not private.has_permission('members.manage') then raise exception 'not authorized';end if;select * into l from public.legacy_members where id=p_legacy_id for update;if not found or l.claimed_by is not null then raise exception 'legacy_unavailable';end if;if not exists(select 1 from public.profiles p where p.id=p_target_user and(lower(p.handle)=lower(l.legacy_nickname) or lower(p.display_name)=lower(l.legacy_nickname))) then raise exception 'nickname_mismatch';end if;select current_era into era_no from public.qgang_identity_settings where singleton=true;select coalesce(max(member_no),0)+1 into next_no from public.community_memberships;insert into public.community_memberships(user_id,status,member_no,joined_at,ended_at,granted_by,era,seal) values(p_target_user,'active',next_no,l.joined_at::timestamptz,null,auth.uid(),coalesce(era_no,1),null) on conflict(user_id) do update set status='active',joined_at=least(public.community_memberships.joined_at,excluded.joined_at),ended_at=null,granted_by=auth.uid(),updated_at=now();update public.profiles set role=case when role='guest' then 'member'::public.qgang_role else role end,updated_at=now() where id=p_target_user;if l.birth_date is not null then insert into public.profile_private(user_id,birth_date,updated_at) values(p_target_user,l.birth_date,now()) on conflict(user_id) do update set birth_date=excluded.birth_date,updated_at=now();update public.profiles set birthday_day=extract(day from l.birth_date)::smallint,birthday_month=extract(month from l.birth_date)::smallint,birthday_year=extract(year from l.birth_date)::smallint where id=p_target_user;end if;update public.legacy_members set claimed_by=p_target_user,claimed_at=now(),verified_by=auth.uid() where id=p_legacy_id;perform public.qgang_sync_automatic_badges(p_target_user);end$$;revoke all on function public.link_legacy_member(bigint,uuid) from public;grant execute on function public.link_legacy_member(bigint,uuid) to authenticated;
create or replace function public.list_today_community_birthdays() returns table(id uuid,display_name text,handle text,avatar_url text,birthday_day smallint,birthday_month smallint) language plpgsql stable security definer set search_path='public','pg_temp' as $$ declare today date:=(now() at time zone 'Europe/Istanbul')::date;begin if auth.uid() is null or not exists(select 1 from public.community_memberships x where x.user_id=auth.uid() and x.status='active') then return;end if;return query select p.id,p.display_name,p.handle,p.avatar_url,extract(day from pp.birth_date)::smallint,extract(month from pp.birth_date)::smallint from public.profiles p join public.community_memberships cm on cm.user_id=p.id and cm.status='active' join public.profile_private pp on pp.user_id=p.id where p.role<>'guest' and extract(month from pp.birth_date)=extract(month from today) and extract(day from pp.birth_date)=extract(day from today) order by p.display_name;end$$;revoke all on function public.list_today_community_birthdays() from public;grant execute on function public.list_today_community_birthdays() to authenticated;
create or replace function public.list_upcoming_member_birthdays() returns table(id uuid,display_name text,handle text,avatar_url text,birthday_day smallint,birthday_month smallint,days_until integer) language plpgsql stable security definer set search_path='public','private','pg_temp' as $$ declare today date:=(now() at time zone 'Europe/Istanbul')::date;begin if auth.uid() is null or not private.has_permission('members.view') then raise exception 'not authorized';end if;return query with b as(select p.id,p.display_name,p.handle,p.avatar_url,extract(day from pp.birth_date)::int bd,extract(month from pp.birth_date)::int bm from public.profiles p join public.community_memberships cm on cm.user_id=p.id and cm.status='active' join public.profile_private pp on pp.user_id=p.id where p.role<>'guest'),n as(select b.*,case when make_date(extract(year from today)::int,bm,bd)>=today then make_date(extract(year from today)::int,bm,bd) else make_date(extract(year from today)::int+1,bm,bd) end next_date from b) select n.id,n.display_name,n.handle,n.avatar_url,n.bd::smallint,n.bm::smallint,(n.next_date-today)::int from n where n.next_date between today and today+7 order by n.next_date,n.display_name;end$$;revoke all on function public.list_upcoming_member_birthdays() from public;grant execute on function public.list_upcoming_member_birthdays() to authenticated;
